# Moringa OS Virtualized Sandbox Security Profile
# Author: Wrld Xavier | Wrld Tech

[sandbox]
engine = "bubblewrap-seccomp-v2"
rootfs_mode = "read-only-overlayfs"
ephemeral_tmpfs = true
unshare_all = true
die_with_parent = true

[resources]
